-- Ensina-me: verified final state for internship V-VI and integration seminar.
-- Idempotent migration generated from the current database.

update public.material_sections ms
set content=v.content,updated_at=now()
from (values
($$Estágio Curricular Supervisionado V$$,$$Atuação em contextos educacionais diversos$$,1,$$Experiências em diferentes contextos ampliam entendimento sobre possibilidades e limites da atuação do pedagogo. A experiência deve ser discutida com supervisão e relacionada às evidências produzidas no campo, para que autonomia, responsabilidade e adaptação sejam aprendidas de forma consciente.$$),
($$Estágio Curricular Supervisionado V$$,$$Atuação em contextos educacionais diversos$$,2,$$O estudo de atuação em contextos educacionais diversos deve ajudar o estudante a relacionar experiência, conhecimento e responsabilidade profissional. A experiência deve ser discutida com supervisão e relacionada às evidências produzidas no campo, para que autonomia, responsabilidade e adaptação sejam aprendidas de forma consciente.$$),
($$Estágio Curricular Supervisionado V$$,$$Atuação em contextos educacionais diversos$$,3,$$Registre contexto, sujeitos, decisões, recursos e evidências relevantes para compreender atuação em contextos educacionais diversos. A experiência deve ser discutida com supervisão e relacionada às evidências produzidas no campo, para que autonomia, responsabilidade e adaptação sejam aprendidas de forma consciente.$$),
($$Estágio Curricular Supervisionado V$$,$$Atuação em contextos educacionais diversos$$,4,$$Imagine uma situação de estágio em que atuação em contextos educacionais diversos esteja presente e descreva quais decisões seriam necessárias. A experiência deve ser discutida com supervisão e relacionada às evidências produzidas no campo, para que autonomia, responsabilidade e adaptação sejam aprendidas de forma consciente.$$),
($$Estágio Curricular Supervisionado V$$,$$Atuação em contextos educacionais diversos$$,5,$$Analise um caso de campo e identifique problema, evidências disponíveis, responsabilidades e alternativas possíveis. A experiência deve ser discutida com supervisão e relacionada às evidências produzidas no campo, para que autonomia, responsabilidade e adaptação sejam aprendidas de forma consciente.$$),
($$Estágio Curricular Supervisionado V$$,$$Atuação em contextos educacionais diversos$$,6,$$Um erro frequente é confundir estágio com simples observação ou execução de tarefas, sem análise e reflexão profissional. A experiência deve ser discutida com supervisão e relacionada às evidências produzidas no campo, para que autonomia, responsabilidade e adaptação sejam aprendidas de forma consciente.$$),
($$Estágio Curricular Supervisionado V$$,$$Atuação em contextos educacionais diversos$$,7,$$A formação inicial docente relaciona conhecimentos profissionais, prática, reflexão e compromisso com a escola e com a aprendizagem. A experiência deve ser discutida com supervisão e relacionada às evidências produzidas no campo, para que autonomia, responsabilidade e adaptação sejam aprendidas de forma consciente.$$),
($$Estágio Curricular Supervisionado V$$,$$Atuação em contextos educacionais diversos$$,8,$$Use atuação em contextos educacionais diversos para registrar uma situação real e justificar a decisão tomada com base em evidências e referenciais do curso. A experiência deve ser discutida com supervisão e relacionada às evidências produzidas no campo, para que autonomia, responsabilidade e adaptação sejam aprendidas de forma consciente.$$),
($$Estágio Curricular Supervisionado V$$,$$Atuação em contextos educacionais diversos$$,9,$$Experiências em diferentes contextos ampliam entendimento sobre possibilidades e limites da atuação do pedagogo. Domínio envolve agir, analisar a própria ação e reconstruir decisões a partir da experiência. A experiência deve ser discutida com supervisão e relacionada às evidências produzidas no campo, para que autonomia, responsabilidade e adaptação sejam aprendidas de forma consciente.$$),
($$Estágio Curricular Supervisionado V$$,$$Atuação em contextos educacionais diversos$$,10,$$Explique atuação em contextos educacionais diversos e escreva qual evidência de campo ajudaria a demonstrar essa aprendizagem. A experiência deve ser discutida com supervisão e relacionada às evidências produzidas no campo, para que autonomia, responsabilidade e adaptação sejam aprendidas de forma consciente.$$),
